import itertools
import random
def sorted_triplets(result):
    # Put a result in a standard order, so that any valid order of triplets and of numbers passes.
    assert isinstance(result, list), f"expected a list of triplets, got {result!r}"
    for triplet in result:
        assert len(triplet) == 3, f"every triplet needs exactly three numbers, got {triplet!r}"
    return sorted(sorted(triplet) for triplet in result)
def brute_force(nums):
    found = set()
    for i, j, k in itertools.combinations(range(len(nums)), 3):
        if nums[i] + nums[j] + nums[k] == 0:
            found.add(tuple(sorted((nums[i], nums[j], nums[k]))))
    return sorted(list(triplet) for triplet in found)
def agrees_with_brute_force_on_small_random_lists():
    rng = random.Random(11)
    for _ in range(300):
        nums = [rng.randint(-5, 5) for _ in range(rng.randint(0, 9))]
        got = sorted_triplets(three_sum(list(nums)))
        assert got == brute_force(nums), f"three_sum({nums}) returned {got}, expected {brute_force(nums)}"
    return True

