def three_sum(nums):
    nums = sorted(nums)                        # sorted: two pointers work, and equal numbers sit side by side
    triplets = []
    for i, a in enumerate(nums):
        if a > 0:
            break                              # the smallest of the three is positive, so the sum cannot be 0
        if i and a == nums[i - 1]:
            continue                           # same first number as the last round: same triplets again
        low, high = i + 1, len(nums) - 1
        while low < high:
            total = a + nums[low] + nums[high]
            if total < 0:
                low += 1
            elif total > 0:
                high -= 1
            else:
                triplets.append([a, nums[low], nums[high]])
                low += 1
                while low < high and nums[low] == nums[low - 1]:
                    low += 1                   # skip repeats of the second number
    return triplets
